def longest_balanced_substring(s):
    """
    Finds the length of the longest balanced substring in the given string s.
    A balanced substring has an equal number of opening and closing parentheses.
    """
    max_len = 0
    stack = [-1]  # Initial index to handle base case

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                max_len = max(max_len, i - stack[-1])

    return max_len

```

