def majority_element(nums):
    """
    Returns the majority element based on specified rules:
    - If the array has an odd number of elements, return the element with the highest frequency.
    - If the array has an even number of elements, return the element with the highest frequency, excluding elements that occur only once.
    """
    if not nums:
        return None

    freq_dict = {}
    for num in nums:
        freq_dict[num] = freq_dict.get(num, 0) + 1

    n = len(nums)

    if n % 2 == 1:
        # Odd number of elements
        max_freq = max(freq_dict.values())
        return min([num for num, freq in freq_dict.items() if freq == max_freq])
    else:
        # Even number of elements
        filtered_dict = {num: freq for num, freq in freq_dict.items() if freq > 1}
        if not filtered_dict:
            return None
        max_freq = max(filtered_dict.values())
        return min([num for num, freq in filtered_dict.items() if freq == max_freq])

