import heapq


def largest_three_unique_numbers(nums):
    """
    Returns the largest three unique numbers from the list using heap.
    """
    if not nums:
        return []

    min_heap = []
    unique_nums = set()

    for num in nums:
        if num not in unique_nums:
            heapq.heappush(min_heap, num)
            unique_nums.add(num)
            if len(min_heap) > 3:
                unique_nums.remove(heapq.heappop(min_heap))

    return sorted(min_heap, reverse=True)

```

