def find_pairs_with_same_remainder(arr):
    """
    Finds all pairs of elements in the array that have the same remainder when divided by 5.

    :param arr: List of integers
    :return: List of tuples, each containing a pair of integers from the array with the same remainder when divided by 5
    """
    remainders = {}
    pairs = []

    for num in arr:
        remainder = num % 5
        if remainder in remainders:
            remainders[remainder].append(num)
        else:
            remainders[remainder] = [num]

    for remainder, nums in remainders.items():
        if len(nums) >= 2:
            for i in range(len(nums)):
                for j in range(i + 1, len(nums)):
                    pairs.append((nums[i], nums[j]))

    return pairs

```

