def create_parameters(input_dict):
    """
    Transforms a dictionary of column names and values into a dictionary
    of parameters with their respective types.
    """
    type_mapping = {
        int: "integer",
        float: "float",
        str: "text"
    }

    output_dict = {}
    for key, value in input_dict.items():
        value_type = type_mapping[type(value)]
        output_dict[key] = {"value": value, "type": value_type}

    return output_dict

```

