def calculate_word_values(words):
    """
    Calculates the value of each word in the list based on its position.
    For repeated words, it only adds the value once using 2 to the power of the position.
    """
    word_values = {}
    for i, word in enumerate(words, start=1):
        if word not in word_values:
            word_values[word] = 2 ** i + i
    return word_values

```

