def check_brackets_balance(s):
    """
    Returns True if the brackets in the string `s` are balanced, otherwise False.
    Handles `()`, `{}`, and `[]` brackets.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map:
            if not stack or stack.pop() != bracket_map[char]:
                return False

    return not stack

```

