def evaluate_postfix(expression):
    """
    Evaluates a postfix (Reverse Polish) notation expression and returns the result as a float.

    Parameters:
        expression (str): The postfix expression to evaluate.

    Returns:
        float: The result of the evaluation.
    """
    stack = []
    tokens = expression.split()

    for token in tokens:
        if token.isdigit():
            stack.append(int(token))
        else:
            b = stack.pop()
            a = stack.pop()

            if token == '+':
                result = a + b
            elif token == '-':
                result = a - b
            elif token == '*':
                result = a * b
            elif token == '/':
                result = a / b

            stack.append(result)

    return float(stack.pop())

```

