def print_last_two(lst):
    """
    Print the last two elements of a list recursively. If the list has less than two elements,
    return an appropriate message.
    """
    if len(lst) == 0:
        return "The list is empty"
    elif len(lst) == 1:
        return "The list has only one element: " + str(lst[0])

    def helper(index, last, second_last):
        if index == len(lst):
            return second_last, last
        return helper(index + 1, lst[index], last)

    second_last, last = helper(1, lst[0], None)
    return f"Last element: {last}, Second last element: {second_last}"

```

