def validate_payment_card(card_number: str) -> str:
    """
    Validates and identifies the type of the payment card.
    :param card_number: Input payment card number as a string.
    :return: A string indicating the type of card ("Visa", "MasterCard", "American Express") or "Invalid".
    """
    # Remove any leading or trailing spaces
    card_number = card_number.strip()

    if len(card_number) == 16:
        if card_number[0] == '4':
            return "Visa"
        elif card_number[:2] in ['51', '52', '53', '54', '55']:
            return "MasterCard"
    elif len(card_number) == 15:
        if card_number[:2] in ['34', '37']:
            return "American Express"

    return "Invalid"

