def find_first_one(sequence):
    """
    Returns the index of the first occurrence of 1 in the given bit sequence.
    If there is no 1 in the sequence, returns -1.
    """
    left, right = 0, len(sequence) - 1

    while left <= right:
        mid = (left + right) // 2
        if sequence[mid] == 1:
            if mid == 0 or sequence[mid - 1] == 0:
                return mid
            else:
                right = mid - 1
        else:
            left = mid + 1

    return -1

```

