def max_depth(nested_list):
    """
    Returns the maximum depth of a given nested list.
    """
    if not isinstance(nested_list, list):
        return 0
    elif not nested_list:
        return 1
    else:
        return 1 + max(max_depth(item) for item in nested_list)

