def evaluate_expression(expression):
    """
    Evaluates a mathematical expression given as a string. The expression can include
    addition, subtraction, multiplication, division, and parentheses. The function
    handles the correct order of operations (PEMDAS/BODMAS).
    """
    import re

    def tokenize(expr):
        tokens = re.findall(r'[\d.]+|[-+*/()]', expr)
        return [float(token) if token.isdigit() or re.match(r'^\d+?\.\d+?$', token) else token for token in tokens]

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(left / right)

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def process_expression(tokens):
        values = []
        operators = []
        i = 0

        while i < len(tokens):
            if isinstance(tokens[i], float):
                values.append(tokens[i])
            elif tokens[i] == '(':
                operators.append(tokens[i])
            elif tokens[i] == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()
            else:
                while (operators and precedence(operators[-1]) >= precedence(tokens[i])):
                    apply_operator(operators, values)
                operators.append(tokens[i])
            i += 1

        while operators:
            apply_operator(operators, values)

        return values[0]

    tokens = tokenize(expression)
    return process_expression(tokens)

```

