import re


def markdown_to_html(markdown_text):
    """
    Converts Markdown formatted text into HTML.
    """
    html_text = []

    if not markdown_text.strip():
        return ""

    paragraphs = markdown_text.strip().split("\n\n")

    for para in paragraphs:
        lines = para.split("\n")
        for line in lines:
            line = re.sub(r"(?<!\\)\*\*(.*?)\*\*", r"<b>\1</b>", line)  # Bold
            line = re.sub(r"(?<!\\)_(.*?)_", r"<i>\1</i>", line)        # Italic

            if line.startswith('### '):
                html_text.append(f"<h3>{line[4:]}</h3>")
            elif line.startswith('## '):
                html_text.append(f"<h2>{line[3:]}</h2>")
            elif line.startswith('# '):
                html_text.append(f"<h1>{line[2:]}</h1>")
            else:
                html_text.append(f"<p>{line}</p>")

    return ''.join(html_text)

```

