def longest_balanced_substring(s: str) -> int:
    """
    Returns the length of the longest balanced substring in a given string where a balanced string 
    contains equal numbers of 'A' and 'B' characters.
    """
    # Map to keep track of the first occurrence of each difference
    diff_map = {0: -1}
    max_length = 0
    count = 0

    for i, char in enumerate(s):
        if char == 'A':
            count += 1
        else:
            count -= 1

        if count in diff_map:
            max_length = max(max_length, i - diff_map[count])
        else:
            diff_map[count] = i

    return max_length

```

