def detect_circular_dependency(tasks):
    """
    Determines if there is a circular dependency in the given tasks.
    :param tasks: Dictionary where keys are task identifiers and values are lists of task identifiers that the given task depends on.
    :return: True if there is a circular dependency, otherwise False.
    """
    def dfs(task, visited, stack):
        visited.add(task)
        stack.add(task)

        for dependency in tasks.get(task, []):
            if dependency not in visited:
                if dfs(dependency, visited, stack):
                    return True
            elif dependency in stack:
                return True

        stack.remove(task)
        return False

    visited = set()
    for task in tasks:
        if task not in visited:
            if dfs(task, visited, set()):
                return True

    return False

```

