import re


def evaluate_expression(expression: str) -> float:
    """
    Evaluate the given mathematical expression and return the result.

    Parameters:
        expression (str): A string representing a mathematical expression which may include 
                          +, -, *, / operators, parentheses, and whitespace.

    Returns:
        float: The result of evaluating the expression.
    """
    def eval_inner(expr):
        tokens = re.findall(r'\d+\.?\d*|\+|\-|\*|\/|\(|\)', expr)
        def evaluate(tokens):
            def get_next_token():
                return tokens.pop(0) if tokens else None

            def parse_expression():
                token = get_next_token()
                if token == '(':
                    value = parse_add_sub()
                    get_next_token()  # should be ')'
                    return value
                return float(token)

            def parse_term():
                value = parse_expression()
                while tokens:
                    token = get_next_token()
                    if token == '*':
                        value *= parse_expression()
                    elif token == '/':
                        value /= parse_expression()
                    else:
                        tokens.insert(0, token)
                        break
                return value

            def parse_add_sub():
                value = parse_term()
                while tokens:
                    token = get_next_token()
                    if token == '+':
                        value += parse_term()
                    elif token == '-':
                        value -= parse_term()
                    else:
                        tokens.insert(0, token)
                        break
                return value

            return parse_add_sub()

        return evaluate(tokens)

    expr = expression.replace(' ', '')
    return eval_inner(expr)

```

