def find_duplicates(nums: list[int]) -> list[int]:
    """
    Returns a list of duplicates appearing in `nums` in the order they first appear.
    """
    if not nums:
        return []

    seen = {}
    duplicates = []

    for num in nums:
        if num in seen:
            if seen[num] == 1:
                duplicates.append(num)
            seen[num] += 1
        else:
            seen[num] = 1

    return duplicates

```

