def min_deletions_to_make_strings_same(str1, str2):
    """
    Return the minimum number of deletions required to make two strings the same.
    """
    # Find the length of the longest common subsequence
    def longest_common_subsequence(str1, str2):
        m, n = len(str1), len(str2)
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if str1[i - 1] == str2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
        return dp[m][n]

    lcs_length = longest_common_subsequence(str1, str2)
    # Minimum deletions to make the strings the same
    return (len(str1) - lcs_length) + (len(str2) - lcs_length)

```

