def unique_items(lst):
    """
    Returns a list of unique items in the given list without using any built-in
    functions, data structures, or algorithms for removing duplicates.
    """
    item_count = {}
    for item in lst:
        if item not in item_count:
            item_count[item] = 1

    unique_lst = []
    for item in lst:
        if item_count[item] == 1:
            unique_lst.append(item)
            item_count[item] = 0  # ensures item is only added once

    return unique_lst

```

