def is_legitimate(orders):
    """
    Check if the list of orders is legitimate.

    Args:
    orders (list of str): List of Buy/Sell/Hold orders.

    Returns:
    bool: True if the orders are legitimate, False otherwise.
    """
    import re
    buy_orders = {}
    sell_orders = {}
    hold_count = 0

    for order in orders:
        order = order.strip()
        if order.startswith("Buy"):
            match = re.match(r"Buy (\d+) shares of (\w+)", order)
            if match:
                amount, symbol = match.groups()
                amount = int(amount)
                if symbol in buy_orders:
                    buy_orders[symbol] += amount
                else:
                    buy_orders[symbol] = amount
        elif order.startswith("Sell"):
            match = re.match(r"Sell (\d+) shares of (\w+)", order)
            if match:
                amount, symbol = match.groups()
                amount = int(amount)
                if symbol in sell_orders:
                    sell_orders[symbol] += amount
                else:
                    sell_orders[symbol] = amount
        elif order == "Hold":
            hold_count += 1
        else:
            return False

    for symbol in buy_orders:
        if symbol not in sell_orders or sell_orders[symbol] != buy_orders[symbol]:
            return False

    return hold_count * 2 == len(orders) - hold_count

```

