def sort_num(arr):
    """
    Sorts a list of non-negative integers in ascending order using bubble sort.
    """
    n = len(arr)
    for i in range(n - 1):
        for j in range(n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr

```

