def is_valid(s: str) -> bool:
    """
    Determine if the input string containing only parentheses is valid.

    Args:
    s (str): Input string containing only parentheses.

    Returns:
    bool: True if the input string is valid, otherwise False.
    """
    stack = []
    brackets = {")": "(", "}": "{", "]": "["}

    for char in s:
        if char in brackets.values():
            stack.append(char)
        elif char in brackets.keys():
            if stack and stack[-1] == brackets[char]:
                stack.pop()
            else:
                return False
        else:
            return False

    return len(stack) == 0

```

