def trim_spaces(s):
    """
    Trims leading and trailing spaces from a string using recursion.
    """
    def trim_leading_spaces(s, start):
        if start >= len(s) or s[start] != ' ':
            return start
        return trim_leading_spaces(s, start + 1)

    def trim_trailing_spaces(s, end):
        if end < 0 or s[end] != ' ':
            return end
        return trim_trailing_spaces(s, end - 1)

    start = trim_leading_spaces(s, 0)
    end = trim_trailing_spaces(s, len(s) - 1)

    def recurse_trim(s, i, max_i):
        if i > max_i:
            return ""
        return s[i] + recurse_trim(s, i + 1, max_i)

    if start > end:
        return ""
    return recurse_trim(s, start, end)

