def count_primes_in_range(a, b):
    """
    Calculate the total number of prime numbers within a given range [a, b], inclusive.
    """

    def is_prime(n):
        """Helper function to check if a number is prime."""
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    prime_count = sum(1 for x in range(a, b + 1) if is_prime(x))
    return prime_count

```

