def min_cut_palindrome(s):
    """
    Returns the minimum number of cuts needed to partition a string into palindromic substrings.
    """
    n = len(s)
    if n < 2:
        return 0

    # Create a 2D array to store if s[i:j+1] is palindrome
    palindrome = [[False] * n for _ in range(n)]

    for length in range(1, n + 1):
        for start in range(n - length + 1):
            end = start + length - 1
            if length == 1:
                palindrome[start][end] = True
            elif length == 2:
                palindrome[start][end] = s[start] == s[end]
            else:
                palindrome[start][end] = (s[start] == s[end]) and palindrome[start + 1][end - 1]

    # Define cuts array, where cuts[i] represents the minimum cuts needed for s[0:i+1]
    cuts = [float('inf')] * n
    for i in range(n):
        if palindrome[0][i]:
            cuts[i] = 0
        else:
            for j in range(i):
                if palindrome[j + 1][i]:
                    cuts[i] = min(cuts[i], cuts[j] + 1)

    return cuts[-1]

```

