def max_frequency_char(s):
    """
    Returns the character that appears the maximum number of times in the input string.
    If multiple characters have the same highest frequency, returns the one
    that appears first in the string.
    """
    char_count = {}

    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    max_freq = 0
    max_char = ''

    for char in s:
        if char_count[char] > max_freq:
            max_freq = char_count[char]
            max_char = char

    return max_char

```

