def evaluate_expression(expression: str) -> int:
    """
    Evaluates a mathematical expression containing integers, addition ('+'), and multiplication ('*'), 
    following the standard order of operations (PEMDAS/BODMAS).
    """

    def evaluate(tokens):
        stack = []
        current_operator = '+'
        current_number = 0

        for token in tokens:
            if token.isdigit():
                current_number = int(token)
            elif token == '+' or token == '*':
                if current_operator == '+':
                    stack.append(current_number)
                elif current_operator == '*':
                    stack.append(stack.pop() * current_number)
                current_operator = token
                current_number = 0

        if current_operator == '+':
            stack.append(current_number)
        elif current_operator == '*':
            stack.append(stack.pop() * current_number)

        return sum(stack)

    # tokenize the expression
    tokens = []
    current_number = ''
    for char in expression:
        if char.isdigit():
            current_number += char
        else:
            if current_number:
                tokens.append(current_number)
                current_number = ''
            tokens.append(char)

    if current_number:
        tokens.append(current_number)

    return evaluate(tokens)

```

