def calculate_fine(overdue_days: int) -> float:
    """
    Calculate the fine for overdue books based on the number of days overdue.

    :param overdue_days: An integer representing the number of days the book is overdue.
    :return: A float representing the total fine in dollars.
    :raises ValueError: If the number of overdue days is negative.
    """
    if overdue_days < 0:
        raise ValueError("Overdue days cannot be negative!")

    if overdue_days <= 5:
        return 0.50 * overdue_days
    elif overdue_days <= 10:
        return 0.50 * 5 + 1.00 * (overdue_days - 5)
    else:
        return 0.50 * 5 + 1.00 * 5 + 5.00 * (overdue_days - 10)

