def is_one_char_away(s1, s2):
    """
    Determines if s1 is one character away from s2.
    One character away means you can insert, remove, or replace exactly one character in s1 to make it equal to s2.
    """
    len_s1, len_s2 = len(s1), len(s2)

    if abs(len_s1 - len_s2) > 1:
        return False

    if len_s1 > len_s2:
        s1, s2 = s2, s1
        len_s1, len_s2 = len_s2, len_s1

    i, j, count_diff = 0, 0, 0

    while i < len_s1 and j < len_s2:
        if s1[i] != s2[j]:
            if count_diff == 1:
                return False
            count_diff += 1
            if len_s1 == len_s2:
                i += 1
        else:
            i += 1
        j += 1

    if i < len_s1 or j < len_s2:
        count_diff += 1

    return count_diff == 1

```

