def max_profit(prices):
    """
    Returns the maximum profit achievable from buying at one day and selling at a later day.
    If no profit can be made, returns -1.
    """
    if not prices:
        return -1

    min_price = prices[0]
    max_profit = 0

    for price in prices[1:]:
        if price < min_price:
            min_price = price
        else:
            profit = price - min_price
            if profit > max_profit:
                max_profit = profit

    return max_profit if max_profit > 0 else -1

```

