def find_anagram_pairs(strings):
    """
    Returns a list of tuples, where each tuple contains a pair of anagrams from the input list of strings.
    """
    anagram_map = {}
    for string in strings:
        # Sort each string to get the canonical form
        sorted_string = ''.join(sorted(string))
        if sorted_string in anagram_map:
            anagram_map[sorted_string].append(string)
        else:
            anagram_map[sorted_string] = [string]

    # Collect pairs of anagrams from the hashmap
    anagram_pairs = []
    for string_list in anagram_map.values():
        if len(string_list) > 1:
            for i in range(len(string_list)):
                for j in range(i + 1, len(string_list)):
                    anagram_pairs.append((string_list[i], string_list[j]))

    return anagram_pairs

```

