def sum_of_squares_of_even(numbers):
    """
    Returns the sum of squares of all even numbers in the list.
    Raises a TypeError if the input is not a list or if the list contains non-integer elements.
    """
    if not isinstance(numbers, list):
        raise TypeError("Input should be a list of integers")

    for num in numbers:
        if not isinstance(num, int):
            raise TypeError("List elements should be integers")

    return sum(num**2 for num in numbers if num % 2 == 0)

```

