def to_json(obj):
    """
    Converts a Python object to a JSON string representation.
    Supported types: dict, list, tuple, str, int, float, boolean, and None.
    """
    if isinstance(obj, str):
        return f'"{obj}"'
    elif isinstance(obj, bool):
        return "true" if obj else "false"
    elif obj is None:
        return "null"
    elif isinstance(obj, (int, float)):
        return str(obj)
    elif isinstance(obj, list) or isinstance(obj, tuple):
        items = [to_json(item) for item in obj]
        return f'[{", ".join(items)}]'
    elif isinstance(obj, dict):
        items = [f'{to_json(key)}: {to_json(value)}' for key, value in obj.items()]
        return f'{{{", ".join(items)}}}'
    else:
        raise TypeError(f"Type {type(obj)} not supported")

```

