def is_anagram(s1, s2):
    """
    Check if s1 and s2 are anagrams considering case sensitivity and special characters.
    """
    if len(s1) != len(s2):
        return False

    def count_characters(string):
        count = {}
        for char in string:
            if char in count:
                count[char] += 1
            else:
                count[char] = 1
        return count

    count1 = count_characters(s1)
    count2 = count_characters(s2)

    return count1 == count2

```

