def is_heap(arr, heap_type):
    """
    Determines whether the array represents a max heap or a min heap.

    Parameters:
    arr (list): The array of integers.
    heap_type (str): The type of heap, either 'min' or 'max'.

    Returns:
    bool: True if the array represents the specified type of heap, False otherwise.
    """
    n = len(arr)
    for i in range(n):
        children = []
        for j in range(2 * i + 1, 2 * i + 3):
            if j < n:
                children.append(arr[j])

        for child in children:
            if heap_type == 'min':
                if arr[i] > child:
                    return False
            elif heap_type == 'max':
                if arr[i] < child:
                    return False
            else:
                raise ValueError("Heap type must be 'min' or 'max'")
    return True

```

