def quick_select_dual_pivot(arr, k):
    """
    Returns the kth smallest element in the array using the Dual-Pivot Quick Select algorithm.
    """
    if not arr:
        return None

    def partition(arr, low, high):
        if arr[low] > arr[high]:
            arr[low], arr[high] = arr[high], arr[low]
        pivot1, pivot2 = arr[low], arr[high]
        i, k, j = low + 1, low + 1, high - 1

        while k <= j:
            if arr[k] < pivot1:
                arr[i], arr[k] = arr[k], arr[i]
                i += 1
            elif arr[k] > pivot2:
                while arr[j] > pivot2 and k < j:
                    j -= 1
                arr[k], arr[j] = arr[j], arr[k]
                j -= 1
                if arr[k] < pivot1:
                    arr[i], arr[k] = arr[k], arr[i]
                    i += 1
            k += 1

        i -= 1
        j += 1

        arr[low], arr[i] = arr[i], arr[low]
        arr[high], arr[j] = arr[j], arr[high]

        return i, j

    def quick_select(arr, low, high, k):
        if low >= high:
            return arr[low]

        pivot1, pivot2 = partition(arr, low, high)

        if k < pivot1:
            return quick_select(arr, low, pivot1 - 1, k)
        elif k > pivot2:
            return quick_select(arr, pivot2 + 1, high, k)
        else:
            return arr[k]

    return quick_select(arr, 0, len(arr) - 1, k - 1)

```

